do $$ declare r record; begin for r in select p.oid::regprocedure as f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('business_manage_campaign','business_manage_contest','business_manage_event','business_manage_location','business_manage_promotion','business_manage_qr','create_qr_engagement_program','list_qr_engagement_programs','business_engagement_analytics','get_business_engagement_funnel','location_engagement_metrics') loop execute format('revoke execute on function %s from anon',r.f); execute format('grant execute on function %s to authenticated',r.f); end loop; end $$;
